package trie_test

import (
	"testing"

	"github.com/ai-verification/go-trie/internal/trie"
)

func TestInsertAndSearch(t *testing.T) {
	tr := trie.New()
	tr.Insert("apple")
	if !tr.Search("apple") {
		t.Fatal("expected Search(apple)=true")
	}
	if tr.Search("app") {
		t.Fatal("Search(app) should be false — not inserted as a word")
	}
	if tr.Search("") {
		t.Fatal("Search of empty string should be false")
	}
}

func TestStartsWith(t *testing.T) {
	tr := trie.New()
	tr.Insert("apple")
	tr.Insert("app")
	if !tr.StartsWith("app") {
		t.Fatal("StartsWith(app) should be true")
	}
	if !tr.StartsWith("appl") {
		t.Fatal("StartsWith(appl) should be true")
	}
	if tr.StartsWith("xyz") {
		t.Fatal("StartsWith(xyz) should be false")
	}
}

func TestDelete(t *testing.T) {
	tr := trie.New()
	tr.Insert("hello")
	deleted := tr.Delete("hello")
	if !deleted {
		t.Fatal("Delete should return true for existing word")
	}
	if tr.Search("hello") {
		t.Fatal("hello should not be searchable after delete")
	}
}

func TestDeleteNonExistent(t *testing.T) {
	tr := trie.New()
	ok := tr.Delete("ghost")
	if ok {
		t.Fatal("Delete of non-existent word should return false")
	}
}

func TestDeletePreservesPrefix(t *testing.T) {
	tr := trie.New()
	tr.Insert("apple")
	tr.Insert("app")
	tr.Delete("apple")
	if !tr.Search("app") {
		t.Fatal("app should still be searchable after deleting apple")
	}
	if tr.Search("apple") {
		t.Fatal("apple should not be searchable after deletion")
	}
	if !tr.StartsWith("app") {
		t.Fatal("StartsWith(app) should still be true")
	}
}
